const allRows = $input.all();
const matched = allRows.filter(item => TARGET_KEYS.has(item.json.vorgangKey));
if (matched.length !== TARGET_KEYS.size) {
  throw new Error('Erwartet ' + TARGET_KEYS.size + ' Treffer, gefunden ' + matched.length + ' - abbrechen, nicht teilweise schreiben.');
}
return matched.map(item => ({ json: { ...item.json, contentStage: "needs_content", contentErrorReason: "", last_error_code: "", last_error_message: "", last_error_stage: "", next_retry_at: "", retry_count: 0 } }));
